from strings_part11 import S, k
# Translations for the 7 languages that were still showing English: iCloud, the subscription and
# Settings (this part), alerts and rules (part13), KPIs (part14).
# `t` replaces only de, fr, it, pt, ar, hi, zh-Hans and keeps the English and Spanish text, and refuses
# a translation whose placeholders (%@, %1$ld, %lld, %%) differ from the English text.
import re

_SPEC = re.compile(r'%(?:(\d+)\$)?[-+ 0#]*\d*(?:\.\d+)?(?:ll|l|h|hh|q|L|z|t|j)?([@diuoxXfFeEgGaAcCsSpn%])')

def _shape(text):
    # "95 % is" is a literal percent sign after a number, not a placeholder (Text(LocalizedStringKey) never formats it).
    text = re.sub(r'(?<=\d) %(?=[\s,.;:)!?]|$)', '', text)
    out = []
    for m in _SPEC.finditer(text):
        kind = {'d': 'i', 'u': 'i'}.get(m.group(2), m.group(2))
        out.append((m.group(1), kind))
    return sorted(out, key=lambda x: (x[0] or '', x[1]))

# Words that really are the same as in English in that language.
SAME_AS_ENGLISH = {("cloud.privacy.title", "it"), ("rules.notifications", "fr")}

def t(key, de, fr, it, pt, ar, hi, zh):
    assert key in S, "unknown key: " + key
    en, es = S[key][0], S[key][1]
    for lang, text in zip(("de", "fr", "it", "pt", "ar", "hi", "zh"), (de, fr, it, pt, ar, hi, zh)):
        assert _shape(text) == _shape(en), f"{key} [{lang}] placeholders differ: {_shape(en)} vs {_shape(text)}"
        assert text.strip() and (text != en or (key, lang) in SAME_AS_ENGLISH), f"{key} [{lang}] is empty or still English"
    S[key] = (en, es, de, fr, it, pt, ar, hi, zh)

